-- GRAIN: one row per record (spine_entity not determined -- no registry hint available) (COUNTRY+YEAR+CODE unique)
-- SPINE_ENTITY: place  (natural_key: REFUGEES_BY_COUNTRY_OF_ORIGIN, YEAR, CODE)
-- Generated by scripts/generate_staging_models.py from SOURCE_REGISTRY -- deterministic,
-- no LLM. Casts kept as landed (TEXT) -- add explicit type casts by hand once each
-- column's real type is confirmed; this generator has no semantic type knowledge.
-- spine_entity 'place' has no connect/ resolver yet (see connect/spine_entity.py) -- no SPINE_ENTITY_ID emitted.
-- landing table's ingestion timestamp is named INGESTED_AT (no leading underscore) rather than the usual _INGESTED_AT -- confirmed via INFORMATION_SCHEMA, not assumed.

with source as (

    select * from {{ source('ripple_raw', 'XC_OWID_REFUGEES') }}

),

renamed as (

    select
        "ENTITY" as entity,
        "CODE" as code,
        "YEAR" as year,
        "REFUGEES_BY_COUNTRY_OF_ORIGIN" as refugees_by_country_of_origin,
        "WORLD_REGION_ACCORDING_TO_OWID" as world_region_according_to_owid,
        INGESTED_AT as _loaded_at,
        'https://ourworldindata.org/grapher/refugee-population-by-country-or-territory-of-origin.csv?csvType=full' as _source_url

    from source

)

select * from renamed
qualify row_number() over (partition by refugees_by_country_of_origin, year, code order by _loaded_at desc) = 1
